package cn.mop.assetexport;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import cn.mop.persistence.*;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.io.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual existing PG ledger -> actual XLSX -> durable original bytes. No object-store or public download. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresExportPreparationProcessorIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",ROUTE="POST /integration/export-processor";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository jobs;static PostgresManualAssetMetadataRepository source;static ObjectMapper mapper;static String admin,assetId;
    @BeforeAll static void connect()throws Exception{String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(4);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);jobs=new PostgresAssetExportRepository(pool,platform);source=new PostgresManualAssetMetadataRepository(pool,platform,mapper);admin=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("padmin")).isPresent()).findFirst().orElseThrow().id();try(var c=pool.getConnection();var s=c.prepareStatement("SELECT asset_id::text FROM public.mop_asset_manual_details WHERE tenant_id=?::uuid ORDER BY asset_id LIMIT 1")){s.setString(1,TENANT);try(var r=s.executeQuery()){assertTrue(r.next(),"Existing real metadata required");assetId=r.getString(1);}}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static AssetExportJobRepository.Access access(){return new AssetExportJobRepository.Access(admin,TENANT,platform.membership(admin,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static cn.mop.domain.assetmetadata.ManualAssetMetadataRepository.Current current(){var a=access();return source.current(new cn.mop.domain.assetmetadata.ManualAssetMetadataRepository.Access(admin,TENANT,a.permissionVersion(),a.traceId()),assetId);}
    static Claim claim(Filters f,Duration lease){var a=access();var j=mapper.convertValue(platform.idempotentAuthorized(admin,TENANT,ROUTE,UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->jobs.authorizeAcceptance(a),()->jobs.accept(a,f)),Job.class);return jobs.claim(j.id(),"actual-xlsx-processor",lease).orElseThrow();}
    static Filters exact(){var a=current().snapshot().asset();return new Filters(a.type(),a.status(),a.siteId(),a.name());}
    static boolean noPrepared(String id)throws Exception{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT file_bytes IS NULL FROM public.mop_asset_export_job WHERE id=?::uuid")){s.setString(1,id);try(var r=s.executeQuery()){r.next();return r.getBoolean(1);}}}
    @Test void actualFilteredRowsProduceCompleteWorkbookAndMatchingDurableBytes()throws Exception{var claim=claim(exact(),Duration.ofSeconds(30));var expected=source.select(claim.command());assertFalse(expected.rows().isEmpty());var result=new AssetExportPreparationProcessor(jobs,source).prepare(claim);assertEquals(expected.rows().size(),result.prepared().encoding().rowCount());var rendered=expected.rows().stream().map(r->AssetLedgerProjection.fromCurrent(UUID.fromString(TENANT),r)).toList();assertEquals(AssetExportPreparationProcessor.selectionFingerprint(claim.command(),rendered),result.prepared().encoding().selectionSha256());try(var book=new XSSFWorkbook(new ByteArrayInputStream(result.prepared().bytes()))){assertEquals(expected.rows().size()+1,book.getSheetAt(0).getPhysicalNumberOfRows());assertEquals(16,book.getSheetAt(0).getRow(0).getLastCellNum());for(int i=0;i<expected.rows().size();i++){assertEquals(expected.rows().get(i).snapshot().asset().name(),book.getSheetAt(0).getRow(i+1).getCell(0).getStringCellValue());assertEquals(org.apache.poi.ss.usermodel.CellType.BLANK,book.getSheetAt(0).getRow(i+1).getCell(15).getCellType());}}assertTrue(result.prepared().sameContent(jobs.loadWork(claim).prepared()));assertFalse(result.prepared().published());assertEquals(State.RUNNING,jobs.get(access(),claim.jobId()).state());}
    @Test void preparedActualWorkbookResumesWithoutConsultingSourceAgain()throws Exception{var claim=claim(exact(),Duration.ofSeconds(30));var first=new AssetExportPreparationProcessor(jobs,source).prepare(claim);var recovered=new AssetExportPreparationProcessor(jobs,c->{throw new AssertionError("Injected unavailable source must not be consulted after preparation");}).prepare(claim);assertTrue(first.prepared().sameContent(recovered.prepared()));assertEquals(first.claim().version(),recovered.claim().version());}
    @Test void actualEmptySelectionPersistsHeaderOnlyWorkbook()throws Exception{var claim=claim(new Filters(null,null,"",UUID.randomUUID().toString()),Duration.ofSeconds(30));assertTrue(source.select(claim.command()).rows().isEmpty());var result=new AssetExportPreparationProcessor(jobs,source).prepare(claim);assertEquals(0,result.prepared().encoding().rowCount());try(var book=new XSSFWorkbook(new ByteArrayInputStream(result.prepared().bytes()))){assertEquals(1,book.getSheetAt(0).getPhysicalNumberOfRows());assertEquals(16,book.getSheetAt(0).getRow(0).getLastCellNum());}assertFalse(result.prepared().published());}
    @Test void leaseExpiringDuringActualSelectionCannotCommitAnEncodedFile()throws Exception{var claim=claim(exact(),Duration.ofMillis(500));AssetExportSnapshotRepository delayed=c->{var rows=source.select(c);try(var connection=pool.getConnection();var s=connection.createStatement()){s.execute("SELECT pg_sleep(0.55)");}catch(SQLException e){throw new IllegalStateException(e);}return rows;};assertEquals(409,assertThrows(DomainException.class,()->new AssetExportPreparationProcessor(jobs,delayed).prepare(claim)).status);assertTrue(noPrepared(claim.jobId()));}
    @Test void actualEncodingFollowedByAuditFailureDoesNotLeavePreparedBytes()throws Exception{var claim=claim(exact(),Duration.ofSeconds(30));javax.sql.DataSource injected=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(proxy,method,args)->{if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("SYNTHETIC_PROCESSOR_AUDIT_FAILURE","22012");try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});var faulted=new PostgresAssetExportRepository(injected,new PostgresPlatformRepository(injected,mapper));assertEquals(503,assertThrows(DomainException.class,()->new AssetExportPreparationProcessor(faulted,source).prepare(claim)).status);assertTrue(noPrepared(claim.jobId()));assertEquals(claim.version(),jobs.get(access(),claim.jobId()).version());}
}
